output_text:
[
  {
    "id": "cartless_only_in_hand_aisles_or_bays",
    "text": "A shopper may move without a cart only in the entrance/cart area, at designated cart-parking bays, or inside single-file hand-only shelf aisles.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_area": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "cart_parking_bay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "single_file_shelf_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf"
          ]
        },
        "permitted_cartless_area": {
          "or": [
            "entrance_cart_area",
            "cart_parking_bay",
            "single_file_shelf_aisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "permitted_cartless_area"
          }
        ]
      }
    }
  },
  {
    "id": "no_carts_in_single_file_shelf_aisles",
    "text": "Shopping carts are not allowed in single-file shelf aisles, which are pedestrian-only.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf"
          ]
        },
        "pedestrian_only_aisle": "single_file_shelf_aisle"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "pedestrian_only_aisle"
        ]
      }
    }
  },
  {
    "id": "park_before_entering_hand_aisle",
    "text": "Before entering a pedestrian-only single-file shelf aisle, the shopper must already have parked or released the cart.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf"
          ]
        },
        "pedestrian_only_aisle": "single_file_shelf_aisle"
      },
      "events": {
        "enter_pedestrian_aisle_with_cart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "pedestrian_only_aisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enter_pedestrian_aisle_with_cart"
    }
  },
  {
    "id": "drop_cart_only_at_parking_bays",
    "text": "A shopper may detach from or park the cart only at designated wide cart-parking bays near the entrances to hand-only aisles.",
    "abstraction": {
      "state_properties": {
        "cart_parking_bay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "drop_cart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "drop_cart",
          {
            "not": "cart_parking_bay"
          }
        ]
      }
    }
  },
  {
    "id": "no_abandoning_cart_into_main_area",
    "text": "After parking a cart at a hand-aisle bay, the shopper may walk away without the cart only into the adjacent pedestrian-only aisle, not into the main cart area.",
    "abstraction": {
      "state_properties": {
        "cart_parking_bay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "single_file_shelf_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf"
          ]
        },
        "pedestrian_only_aisle": "single_file_shelf_aisle",
        "main_cart_area": {
          "not": "pedestrian_only_aisle"
        }
      },
      "events": {
        "leave_bay_without_cart_to_main_area": {
          "pre": {
            "and": [
              "cart_parking_bay",
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": "main_cart_area"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_bay_without_cart_to_main_area"
    }
  },
  {
    "id": "hand_aisle_requires_hand_shelf_interaction",
    "text": "When a shopper enters a pedestrian-only shelf aisle without the cart, they are obliged to perform the shelf interaction there by hand.",
    "abstraction": {
      "state_properties": {
        "cart_parking_bay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "single_file_shelf_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf"
          ]
        },
        "pedestrian_only_aisle": "single_file_shelf_aisle"
      },
      "events": {
        "enter_hand_aisle": {
          "pre": {
            "and": [
              "cart_parking_bay",
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": "pedestrian_only_aisle"
        },
        "hand_shelf_interaction": {
          "pre": {
            "and": [
              "pedestrian_only_aisle",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "enter_hand_aisle",
      "discharge": "hand_shelf_interaction"
    }
  },
  {
    "id": "retrieve_cart_after_hand_pick",
    "text": "After taking an item by hand from the dead-end single-file shelf aisle, the shopper must return to the cart-parking bay and retrieve the cart.",
    "abstraction": {
      "state_properties": {
        "cart_parking_bay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "dead_end_hand_pick_slot": {
          "or": [
            "at(3,1)",
            "at(6,1)"
          ]
        }
      },
      "events": {
        "hand_pick_at_dead_end": {
          "pre": {
            "and": [
              "dead_end_hand_pick_slot",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": null
        },
        "retrieve_cart": {
          "pre": {
            "and": [
              "cart_parking_bay",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "hand_pick_at_dead_end",
      "discharge": "retrieve_cart"
    }
  },
  {
    "id": "lower_shelf_lane_no_reverse",
    "text": "When pushing a cart along the lower face of a shelf, the shopper must not reverse north or west, but should continue downstream along the lane.",
    "abstraction": {
      "state_properties": {
        "lower_shelf_face": "shelfN",
        "cart_on_lower_shelf_lane": {
          "and": [
            "hasCart",
            "lower_shelf_face"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cart_on_lower_shelf_lane",
          {
            "or": [
              "N",
              "W"
            ]
          }
        ]
      }
    }
  }
]
